import java.nio.file.*;import javax.tools.ToolProvider;import java.net.*;import java.util.*;
/** Actual JDK compilation and bounded-format execution; no Spring/build claim. */
class ScanProbe {
 public static void main(String[]args)throws Exception{Path out=Files.createTempDirectory("pis-t29-classes-");String base="backend/src/main/java/com/pis/";if(ToolProvider.getSystemJavaCompiler().run(null,null,null,"-d",out.toString(),base+"label/LabelBarcode.java",base+"scan/ScanFormat.java",base+"scan/ScanLeasePolicy.java")!=0)throw new AssertionError();try(var loader=new URLClassLoader(new URL[]{out.toUri().toURL()})){var format=loader.loadClass("com.pis.scan.ScanFormat");var labels=loader.loadClass("com.pis.label.LabelBarcode");UUID id=UUID.randomUUID();String barcode=(String)labels.getMethod("create",UUID.class).invoke(null,id);byte[] data=(byte[])format.getMethod("fixture",UUID.class,UUID.class,UUID.class,String.class,int.class,int.class).invoke(null,id,id,id,barcode,32,32);var inspect=format.getMethod("inspect",byte[].class);var result=inspect.invoke(null,(Object)data);var code=result.getClass().getMethod("code");if(!code.invoke(result).equals("SYNTHETIC_HEADER_ONLY"))throw new AssertionError();for(var entry:Map.of("FORMAT_NOT_CONFIGURED",new byte[]{'I','I',42,0},"UNSUPPORTED_ARCHIVE",new byte[]{'P','K',3,4},"INPUT_LIMIT",new byte[513],"UNSUPPORTED_FORMAT","../../file".getBytes()).entrySet())if(!code.invoke(inspect.invoke(null,(Object)entry.getValue())).equals(entry.getKey()))throw new AssertionError();var policy=loader.loadClass("com.pis.scan.ScanLeasePolicy");var start=java.time.Instant.parse("2026-01-01T00:00:00Z");var deadline=(java.time.Instant)policy.getMethod("deadline",java.time.Instant.class).invoke(null,start);if(!deadline.equals(start.plusSeconds(30))||!policy.getMethod("expired",java.time.Instant.class,java.time.Instant.class).invoke(null,deadline,deadline).equals(true)||!policy.getMethod("retryAt",java.time.Instant.class,int.class).invoke(null,start,3).equals(start.plusSeconds(15)))throw new AssertionError();System.out.println("PASS actual scan header: IDs/checksum barcode, TIFF not configured, archive/path rejection and resource cap");}}
}
